// Transport = bidirectional JSON message pipe. Concrete implementations:
//  - worker: browser-basedpyright running as a Web Worker.
//  - ws:     WebSocket to a remote basedpyright server (docs/lsp-server/).

// Patched worker + server file system, generated by scripts/vite-pyright.ts.
import pyrightWorkerUrl from "virtual:pyright-worker-url";
import pyrightFilesUrl from "virtual:pyright-files-url";

export interface RpcMessage {
  jsonrpc: "2.0";
  id?: number | string;
  method?: string;
  params?: unknown;
  result?: unknown;
  error?: { code: number; message: string };
}

export interface Transport {
  send(msg: RpcMessage): void;
  onMessage(handler: (msg: RpcMessage) => void): void;
  onClose(handler: () => void): void;
  dispose(): void;
}

/**
 * The server's virtual file system (stubs at their /workspace paths +
 * pyrightconfig.json; routing in scripts/vite-pyright.ts). Fetched per server
 * start and handed straight to the worker, so the main thread keeps no copy.
 */
async function fetchServerFiles(): Promise<Record<string, string>> {
  const res = await fetch(pyrightFilesUrl);
  if (!res.ok) throw new Error(`LSP stubs: HTTP ${res.status}`);
  return res.json() as Promise<Record<string, string>>;
}

function spawnPyrightWorker(name: string): Worker {
  return new Worker(pyrightWorkerUrl, { name });
}

export function createWorkerTransport(): Transport {
  const worker = spawnPyrightWorker("b2op-hub-lsp");
  worker.postMessage({ type: "browser/boot", mode: "foreground" });

  let msgHandler: ((m: RpcMessage) => void) | null = null;
  let closeHandler: (() => void) | null = null;
  let initInjected = false;
  let pending: RpcMessage[] | null = null;
  let disposed = false;

  worker.onmessage = (ev) => {
    const msg = ev.data as { type?: string; initialData?: unknown; port?: MessagePort } & RpcMessage;

    // Pyright browser asks the main thread to spawn background workers because
    // nested workers are blocked in Safari and unreliable elsewhere.
    // The patched worker never asks for one (background analysis is disabled
    // to save memory); kept so an unpatched worker still works.
    if (msg?.type === "browser/newWorker") {
      console.warn("[b2op-hub-lsp] pyright requested a background worker: is the worker patch applied?");
      const bg = spawnPyrightWorker("b2op-hub-lsp-bg");
      bg.postMessage(
        { type: "browser/boot", mode: "background", initialData: msg.initialData, port: msg.port },
        [msg.port as MessagePort],
      );
      return;
    }

    msgHandler?.(msg);
  };
  worker.onerror = () => closeHandler?.();

  return {
    send(msg) {
      // Inject stubs into the first initialize request via the VFS files map.
      if (!initInjected && msg.method === "initialize") {
        initInjected = true;
        const p = (msg.params ?? {}) as Record<string, unknown>;
        // Messages sent while the files load wait so `initialize` stays first.
        pending = [];
        void fetchServerFiles()
          .then(
            (files) => ({ ...msg, params: { ...p, initializationOptions: { ...((p.initializationOptions as object) ?? {}), files } } }),
            (e) => {
              console.error("[b2op-hub-lsp] failed to load stubs", e);
              return msg;
            },
          )
          .then((enriched) => {
            if (disposed) return;
            worker.postMessage(enriched);
            for (const m of pending ?? []) worker.postMessage(m);
            pending = null;
          });
        return;
      }
      if (pending) pending.push(msg);
      else worker.postMessage(msg);
    },
    onMessage: (h) => (msgHandler = h),
    onClose: (h) => (closeHandler = h),
    dispose: () => {
      disposed = true;
      pending = null;
      worker.terminate();
    },
  };
}

export function createWsTransport(url: string): Promise<Transport> {
  return new Promise((resolve, reject) => {
    const socket = new WebSocket(url);
    const timer = setTimeout(() => {
      socket.close();
      reject(new Error(`LSP WebSocket timeout: ${url}`));
    }, 5000);
    let msgHandler: ((m: RpcMessage) => void) | null = null;
    let closeHandler: (() => void) | null = null;
    socket.onopen = () => {
      clearTimeout(timer);
      resolve({
        send: (msg) => socket.send(JSON.stringify(msg)),
        onMessage: (h) => (msgHandler = h),
        onClose: (h) => (closeHandler = h),
        dispose: () => socket.close(),
      });
    };
    socket.onmessage = (ev) => {
      try {
        msgHandler?.(JSON.parse(typeof ev.data === "string" ? ev.data : ""));
      } catch {
        // ignore malformed frame
      }
    };
    socket.onerror = () => {
      clearTimeout(timer);
      reject(new Error(`LSP WebSocket error: ${url}`));
    };
    socket.onclose = () => closeHandler?.();
  });
}
